export const CODE: Record<string, string> = {
  "brain.py": "\"\"\"RAG brain - four Neurons and three Engrams, a node each.\n\n    python brain.py \"What is a Dendrite and what role does it play?\"\n    python brain.py                  REPL, plus the HTTP API on :8000\n\n  Neurons                                     Engrams\n    ingester   chunk + embed, dual-imprint      rag-vectors   VectorEngram\n    retriever  hybrid recall + RRF fusion       rag-keywords  KeywordEngram\n    reranker   lexical-overlap rescore          rag-cache     InMemoryEngram\n    generator  grounded HF answer, cached\n\nTwo interfaces onto the same nodes: receptors/terminal.py and\nreceptors/api.py. Neither knows the other exists.\n\"\"\"\nimport asyncio\nimport contextlib\nimport signal\n\nfrom cosmonapse import Dendrite, MemorySynapse, connect_synapse, run_brain\n\nfrom config import NAMESPACE, SYNAPSE_URL\nfrom engram.indexes import CACHE, KEYWORDS, VECTORS\nfrom neurons import generator, ingester, reranker, retriever\nfrom receptors import api, terminal\n\n\ndef build_engram(synapse, engram) -> Dendrite:\n    node = Dendrite(synapse=synapse, namespace=NAMESPACE,\n                    dendrite_id=f\"{engram.engram_id}-node\", role=\"worker\")\n    node.attach_engram(engram)\n    return node\n\n\ndef build_neuron(synapse, axon) -> Dendrite:\n    node = Dendrite(synapse=synapse, namespace=NAMESPACE,\n                    dendrite_id=f\"{axon.neuron_id}-node\", role=\"worker\")\n    node.attach_axon(axon)\n    return node\n\n\ndef build_interface(synapse, name: str, receptor) -> Dendrite:\n    \"\"\"Interfaces run the pipeline, so they sit on orchestrator nodes.\"\"\"\n    node = Dendrite(synapse=synapse, namespace=NAMESPACE,\n                    dendrite_id=f\"{name}-node\", heartbeat_s=0)\n    node.attach_receptor(receptor)\n    return node\n\n\ndef _stop_on_signals() -> None:\n    \"\"\"Ctrl-C / SIGTERM cancel the task so run_brain can unwind every node.\"\"\"\n    task = asyncio.current_task()\n    loop = asyncio.get_running_loop()\n    for sig in (signal.SIGINT, signal.SIGTERM):\n        with contextlib.suppress(NotImplementedError, AttributeError):\n            loop.add_signal_handler(sig, task.cancel)\n\n\nasync def main() -> int:\n    _stop_on_signals()\n    if SYNAPSE_URL:\n        synapse = await connect_synapse(SYNAPSE_URL)\n    else:\n        synapse = MemorySynapse()      # in-process bus - no broker, no setup\n        await synapse.connect()\n    try:\n        return await run_brain(\n            *(build_engram(synapse, e) for e in (VECTORS, KEYWORDS, CACHE)),\n            *(build_neuron(synapse, a) for a in (ingester.AXON, retriever.AXON,\n                                                 reranker.AXON, generator.make_axon())),\n            build_interface(synapse, \"terminal\", terminal.RECEPTOR),\n            build_interface(synapse, \"api\", api.RECEPTOR),\n        )\n    except asyncio.CancelledError:\n        return 0\n    finally:\n        await synapse.close()\n\n\nif __name__ == \"__main__\":\n    try:\n        raise SystemExit(asyncio.run(main()))\n    except KeyboardInterrupt:\n        raise SystemExit(130)\n",
  "config.py": "\"\"\"Shared settings for the RAG package.\"\"\"\nimport os\nimport re\nfrom pathlib import Path\n\nfrom dotenv import load_dotenv\n\nROOT = Path(__file__).resolve().parent\nload_dotenv(ROOT.parent / \".env\")               # cosmonapse-examples/.env\n\n# Unset -> in-process MemorySynapse. Set to run over a real synapse.\nSYNAPSE_URL = os.environ.get(\"SYNAPSE_URL\", \"\")\nNAMESPACE = \"rag\"\nGEN_MODEL = os.environ.get(\"RAG_GEN_MODEL\", \"meta-llama/Llama-3.1-8B-Instruct\")\nTOP_K = int(os.environ.get(\"RAG_TOP_K\", \"4\"))\nFETCH_K = int(os.environ.get(\"RAG_FETCH_K\", \"8\"))   # per-backend, pre-fusion\nMIN_SCORE = float(os.environ.get(\"RAG_MIN_SCORE\", \"0.25\"))\nRRF_K = 60\n\nSYSTEM_PROMPT = (\n    \"You answer questions using ONLY the provided context. \"\n    \"If the context does not contain the answer, say so plainly. \"\n    \"Cite sources inline as [doc_id#chunk].\"\n)\n\n\ndef hf_token() -> str:\n    token = os.environ.get(\"HF_TOKEN\", \"\")\n    if not token or token.startswith(\"hf_xxx\"):\n        raise RuntimeError(\"Set a real HF_TOKEN in cosmonapse-examples/.env\")\n    return token\n\n\ndef cache_key(question: str) -> str:\n    return \"q:\" + re.sub(r\"\\W+\", \" \", question.lower()).strip()\n",
  "embeddings.py": "\"\"\"HF embedding client + text chunker for the RAG pipeline.\"\"\"\nfrom __future__ import annotations\n\nimport os\nimport re\n\nimport httpx\n\nEMBED_MODEL = os.environ.get(\n    \"RAG_EMBED_MODEL\", \"sentence-transformers/all-MiniLM-L6-v2\",\n)\nEMBED_URL = os.environ.get(\n    \"RAG_EMBED_URL\",\n    f\"https://router.huggingface.co/hf-inference/models/{EMBED_MODEL}\"\n    \"/pipeline/feature-extraction\",\n)\n\n\nasync def embed(texts: list[str], *, api_key: str, timeout: float = 60.0) -> list[list[float]]:\n    \"\"\"Embed a batch of texts via the HF Inference API.\"\"\"\n    headers = {\n        \"Authorization\": f\"Bearer {api_key}\",\n        \"Content-Type\": \"application/json\",\n    }\n    async with httpx.AsyncClient(timeout=timeout, headers=headers) as client:\n        r = await client.post(EMBED_URL, json={\"inputs\": texts})\n        r.raise_for_status()\n        data = r.json()\n    # Single input may come back as one vector; normalise to list-of-vectors.\n    if data and isinstance(data[0], (int, float)):\n        data = [data]\n    return data\n\n\ndef chunk_text(text: str, *, max_chars: int = 700, overlap: int = 100) -> list[str]:\n    \"\"\"Paragraph-aware sliding-window chunker.\"\"\"\n    paras = [p.strip() for p in re.split(r\"\\n\\s*\\n\", text) if p.strip()]\n    chunks: list[str] = []\n    buf = \"\"\n    for p in paras:\n        if len(buf) + len(p) + 2 <= max_chars:\n            buf = f\"{buf}\\n\\n{p}\" if buf else p\n            continue\n        if buf:\n            chunks.append(buf)\n        # paragraph itself too long: hard-split with overlap\n        while len(p) > max_chars:\n            chunks.append(p[:max_chars])\n            p = p[max_chars - overlap:]\n        buf = p\n    if buf:\n        chunks.append(buf)\n    return chunks\n",
  "engram/indexes.py": "\"\"\"indexes - the three Engrams this brain remembers with.\n\n    VECTORS   rag-vectors   VectorEngram    semantic (cosine)\n    KEYWORDS  rag-keywords  KeywordEngram   lexical (BM25)\n    CACHE     rag-cache     InMemoryEngram  answer memoization\n\nNeurons never import this module; they name the engram ids in their\nEngramBindings. brain.py attaches them, and the interfaces read .size.\n\"\"\"\nfrom cosmonapse import InMemoryEngram\n\nfrom engram.keyword_engram import KeywordEngram\nfrom engram.vector_engram import VectorEngram\n\nVECTORS = VectorEngram(engram_id=\"rag-vectors\", engram_kind=\"semantic\")\nKEYWORDS = KeywordEngram(engram_id=\"rag-keywords\", engram_kind=\"lexical\")\nCACHE = InMemoryEngram(engram_id=\"rag-cache\", engram_kind=\"context\")\n",
  "engram/keyword_engram.py": "\"\"\"KeywordEngram - a BM25-lite lexical Engram backend.\n\nComplements VectorEngram: same entry shape (minus the embedding),\nqueried with {\"text\": str, \"top_k\": int} instead of an embedding.\ncan_serve() keeps the two from answering each other's queries when a\nRECALL is routed by kind instead of id.\n\"\"\"\nfrom __future__ import annotations\n\nimport asyncio\nimport math\nimport re\nimport time\nimport uuid\nfrom collections import Counter\nfrom typing import Any\n\nfrom cosmonapse import Hit\nfrom cosmonapse.engram.base import Engram, ImprintReceipt\n\n_TOKEN = re.compile(r\"[a-z0-9]+\")\n\n\ndef tokenize(text: str) -> list[str]:\n    return _TOKEN.findall(text.lower())\n\n\nclass KeywordEngram(Engram):\n    \"\"\"In-memory inverted index with BM25 scoring (k1=1.5, b=0.75).\n\n    Entry shape (imprint):  {\"text\": str, \"doc_id\": str, \"chunk_index\": int, ...}\n    Query shape (recall):   {\"text\": str, \"top_k\": int = 4}\n    \"\"\"\n\n    K1 = 1.5\n    B = 0.75\n\n    def __init__(\n        self,\n        *,\n        engram_id: str = \"rag-keywords\",\n        engram_kind: str = \"lexical\",\n        version: str | None = \"0.1.0\",\n    ) -> None:\n        self.engram_id = engram_id\n        self.engram_kind = engram_kind\n        self.capabilities = [\"bm25\", \"keyword\", \"merge_key\"]\n        self.version = version\n        self._entries: dict[str, dict[str, Any]] = {}\n        self._tf: dict[str, Counter] = {}      # entry id -> term freq\n        self._df: Counter = Counter()          # term -> doc freq\n        self._merge_keys: dict[str, str] = {}\n        self._lock = asyncio.Lock()\n\n    async def connect(self) -> None: ...\n\n    async def close(self) -> None:\n        self._entries.clear(); self._tf.clear()\n        self._df.clear(); self._merge_keys.clear()\n\n    async def can_serve(self, query: dict[str, Any]) -> bool:\n        return \"text\" in query and \"embedding\" not in query\n\n    # -- index maintenance ------------------------------------------------\n    def _unindex(self, eid: str) -> None:\n        for term in self._tf.pop(eid, ()):\n            self._df[term] -= 1\n            if self._df[term] <= 0:\n                del self._df[term]\n\n    def _index(self, eid: str, entry: dict[str, Any]) -> None:\n        tf = Counter(tokenize(entry.get(\"text\", \"\")))\n        self._tf[eid] = tf\n        for term in tf:\n            self._df[term] += 1\n\n    # -- read ---------------------------------------------------------------\n    async def recall(\n        self,\n        query: dict[str, Any],\n        *,\n        filters: dict[str, Any] | None = None,\n        context_ref: str | None = None,\n        deadline_ms: int | None = None,\n        min_confidence: float | None = None,\n    ) -> list[Hit]:\n        qterms = tokenize(query.get(\"text\", \"\"))\n        if not qterms:\n            return []\n        top_k = int(query.get(\"top_k\", 4))\n\n        async with self._lock:\n            n = len(self._entries)\n            if n == 0:\n                return []\n            avgdl = sum(sum(tf.values()) for tf in self._tf.values()) / n\n            t0 = time.monotonic()\n            scored: list[Hit] = []\n            for eid, entry in self._entries.items():\n                if filters and any(entry.get(k) != v for k, v in filters.items()):\n                    continue\n                tf = self._tf.get(eid, Counter())\n                dl = sum(tf.values()) or 1\n                score = 0.0\n                for term in qterms:\n                    f = tf.get(term, 0)\n                    if not f:\n                        continue\n                    idf = math.log(1 + (n - self._df[term] + 0.5) / (self._df[term] + 0.5))\n                    score += idf * (f * (self.K1 + 1)) / (\n                        f + self.K1 * (1 - self.B + self.B * dl / avgdl)\n                    )\n                if score <= 0.0:\n                    continue\n                if min_confidence is not None and score < min_confidence:\n                    continue\n                scored.append(Hit(id=eid, entry=dict(entry), score=score))\n                if deadline_ms and (time.monotonic() - t0) * 1000 > deadline_ms:\n                    break\n\n        scored.sort(key=lambda h: h.score, reverse=True)\n        return scored[:top_k]\n\n    # -- write ----------------------------------------------------------------\n    async def imprint(\n        self,\n        op: str,\n        entry: dict[str, Any],\n        *,\n        merge_key: str | None = None,\n        imprint_id: str | None = None,\n        trace_id: str | None = None,\n    ) -> ImprintReceipt:\n        t0 = time.monotonic()\n\n        def receipt(eid: str | None, error: str | None = None) -> ImprintReceipt:\n            return ImprintReceipt(\n                engram_id=self.engram_id, op=op, id=eid,\n                took_ms=int((time.monotonic() - t0) * 1000), error=error,\n            )\n\n        async with self._lock:\n            if op == \"delete\":\n                eid = (self._merge_keys.get(merge_key) if merge_key\n                       else entry.get(\"id\"))\n                if eid and eid in self._entries:\n                    old = dict(self._entries[eid])\n                    if merge_key:\n                        self._saga_record(trace_id, \"upsert\", old,\n                                          merge_key=merge_key)\n                    else:\n                        self._saga_record(trace_id, \"add\", {**old, \"id\": eid})\n                    self._unindex(eid)\n                    del self._entries[eid]\n                    self._merge_keys = {\n                        k: v for k, v in self._merge_keys.items() if v != eid\n                    }\n                return receipt(eid)\n\n            if op in (\"merge\", \"upsert\") and merge_key:\n                eid = self._merge_keys.get(merge_key)\n                if eid:\n                    self._saga_record(trace_id, \"upsert\",\n                                      dict(self._entries[eid]),\n                                      merge_key=merge_key)\n                    self._unindex(eid)\n                    if op == \"merge\":\n                        self._entries[eid].update(entry)\n                    else:\n                        self._entries[eid] = dict(entry)\n                    self._index(eid, self._entries[eid])\n                    return receipt(eid)\n\n            if op == \"add\" and merge_key and merge_key in self._merge_keys:\n                return receipt(None, error=f\"merge_key {merge_key!r} exists\")\n\n            eid = imprint_id or f\"kw_{uuid.uuid4().hex[:12]}\"\n            self._entries[eid] = dict(entry)\n            self._index(eid, self._entries[eid])\n            if merge_key:\n                self._merge_keys[merge_key] = eid\n                self._saga_record(trace_id, \"delete\", {}, merge_key=merge_key)\n            else:\n                self._saga_record(trace_id, \"delete\", {\"id\": eid})\n            return receipt(eid)\n\n    @property\n    def size(self) -> int:\n        return len(self._entries)\n",
  "engram/vector_engram.py": "\"\"\"VectorEngram - a cosine-similarity Engram backend.\n\nImplements the cosmonapse Engram ABC so the standard RECALL / IMPRINT\nprotocol carries vector search: entries are chunk dicts holding an\n\"embedding\" list; recall queries carry a query \"embedding\" and \"top_k\".\n\"\"\"\nfrom __future__ import annotations\n\nimport asyncio\nimport math\nimport time\nimport uuid\nfrom typing import Any\n\nfrom cosmonapse import Hit\nfrom cosmonapse.engram.base import Engram, ImprintReceipt\n\n\ndef cosine(a: list[float], b: list[float]) -> float:\n    dot = sum(x * y for x, y in zip(a, b))\n    na = math.sqrt(sum(x * x for x in a))\n    nb = math.sqrt(sum(x * x for x in b))\n    if na == 0.0 or nb == 0.0:\n        return 0.0\n    return dot / (na * nb)\n\n\nclass VectorEngram(Engram):\n    \"\"\"In-memory vector store behind the Engram protocol.\n\n    Entry shape (imprint):\n        {\"text\": str, \"doc_id\": str, \"chunk_index\": int,\n         \"embedding\": list[float], ...any metadata}\n\n    Query shape (recall):\n        {\"embedding\": list[float], \"top_k\": int = 4}\n        filters: {\"doc_id\": str} narrows to one document.\n    \"\"\"\n\n    def __init__(\n        self,\n        *,\n        engram_id: str = \"rag-vectors\",\n        engram_kind: str = \"semantic\",\n        version: str | None = \"0.1.0\",\n    ) -> None:\n        self.engram_id = engram_id\n        self.engram_kind = engram_kind\n        self.capabilities = [\"vector\", \"cosine\", \"merge_key\"]\n        self.version = version\n        self._entries: dict[str, dict[str, Any]] = {}\n        self._merge_keys: dict[str, str] = {}  # merge_key -> entry id\n        self._lock = asyncio.Lock()\n\n    # -- lifecycle -----------------------------------------------------\n    async def connect(self) -> None: ...\n\n    async def close(self) -> None:\n        self._entries.clear()\n        self._merge_keys.clear()\n\n    # -- capability negotiation -----------------------------------------\n    async def can_serve(self, query: dict[str, Any]) -> bool:\n        return \"embedding\" in query\n\n    # -- read ------------------------------------------------------------\n    async def recall(\n        self,\n        query: dict[str, Any],\n        *,\n        filters: dict[str, Any] | None = None,\n        context_ref: str | None = None,\n        deadline_ms: int | None = None,\n        min_confidence: float | None = None,\n    ) -> list[Hit]:\n        t0 = time.monotonic()\n        qvec = query.get(\"embedding\")\n        if not qvec:\n            return []\n        top_k = int(query.get(\"top_k\", 4))\n\n        async with self._lock:\n            items = list(self._entries.items())\n\n        scored: list[Hit] = []\n        for eid, entry in items:\n            if filters and any(entry.get(k) != v for k, v in filters.items()):\n                continue\n            score = cosine(qvec, entry.get(\"embedding\", []))\n            if min_confidence is not None and score < min_confidence:\n                continue\n            # Strip the embedding from the wire reply - it is bulky and\n            # the caller only needs text + metadata + score.\n            slim = {k: v for k, v in entry.items() if k != \"embedding\"}\n            scored.append(Hit(id=eid, entry=slim, score=score))\n            if deadline_ms and (time.monotonic() - t0) * 1000 > deadline_ms:\n                break\n\n        scored.sort(key=lambda h: h.score, reverse=True)\n        return scored[:top_k]\n\n    # -- write -----------------------------------------------------------\n    async def imprint(\n        self,\n        op: str,\n        entry: dict[str, Any],\n        *,\n        merge_key: str | None = None,\n        imprint_id: str | None = None,\n        trace_id: str | None = None,\n    ) -> ImprintReceipt:\n        t0 = time.monotonic()\n\n        def receipt(eid: str | None, error: str | None = None) -> ImprintReceipt:\n            return ImprintReceipt(\n                engram_id=self.engram_id, op=op, id=eid,\n                took_ms=int((time.monotonic() - t0) * 1000), error=error,\n            )\n\n        async with self._lock:\n            if op == \"delete\":\n                eid = (self._merge_keys.get(merge_key) if merge_key\n                       else entry.get(\"id\"))\n                if eid and eid in self._entries:\n                    old = dict(self._entries[eid])\n                    # saga inverse: restore the deleted entry\n                    if merge_key:\n                        self._saga_record(trace_id, \"upsert\", old,\n                                          merge_key=merge_key)\n                    else:\n                        self._saga_record(trace_id, \"add\", {**old, \"id\": eid})\n                    del self._entries[eid]\n                    self._merge_keys = {\n                        k: v for k, v in self._merge_keys.items() if v != eid\n                    }\n                return receipt(eid)\n\n            if op in (\"merge\", \"upsert\") and merge_key:\n                eid = self._merge_keys.get(merge_key)\n                if eid:\n                    # saga inverse: restore the prior content for this key\n                    self._saga_record(trace_id, \"upsert\",\n                                      dict(self._entries[eid]),\n                                      merge_key=merge_key)\n                    if op == \"merge\":\n                        self._entries[eid].update(entry)\n                    else:\n                        self._entries[eid] = dict(entry)\n                    return receipt(eid)\n\n            if op == \"add\" and merge_key and merge_key in self._merge_keys:\n                return receipt(None, error=f\"merge_key {merge_key!r} exists\")\n\n            eid = imprint_id or f\"vec_{uuid.uuid4().hex[:12]}\"\n            self._entries[eid] = dict(entry)\n            if merge_key:\n                self._merge_keys[merge_key] = eid\n                # saga inverse: this key did not exist before  -  delete it\n                self._saga_record(trace_id, \"delete\", {}, merge_key=merge_key)\n            else:\n                self._saga_record(trace_id, \"delete\", {\"id\": eid})\n            return receipt(eid)\n\n    # -- convenience -------------------------------------------------------\n    @property\n    def size(self) -> int:\n        return len(self._entries)\n",
  "helpers.py": "\"\"\"helpers - the ask pipeline and sample ingest, shared by both interfaces.\n\nNot a component: nothing here attaches to a Dendrite. It is what an\ninterface does with the orchestrator node it is mounted on.\n\"\"\"\nfrom __future__ import annotations\n\nfrom pathlib import Path\n\nfrom cosmonapse import new_trace_id\n\nfrom config import ROOT, TOP_K\nfrom engram.indexes import CACHE, KEYWORDS, VECTORS\n\n\nasync def ingest(orchestrator, doc_id: str, text: str) -> dict:\n    reply = await orchestrator.dispatch_and_wait(\n        neuron=\"ingester\", input={\"doc_id\": doc_id, \"text\": text},\n        timeout_s=120.0,\n    )\n    if reply.type.value == \"ERROR\":\n        raise RuntimeError(reply.payload.get(\"message\", \"ingest failed\"))\n    return reply.payload[\"output\"]\n\n\nasync def ingest_samples(orchestrator, folder: Path = ROOT / \"sample_docs\") -> list[dict]:\n    return [await ingest(orchestrator, doc.stem, doc.read_text(encoding=\"utf-8\"))\n            for doc in sorted(folder.glob(\"*\"))]\n\n\nasync def ask_pipeline(orchestrator, question: str, *, top_k: int = TOP_K,\n                       timeout_s: float = 60.0) -> dict:\n    \"\"\"retrieve -> rerank -> generate, chained on ONE trace_id, so Prism\n    shows the whole workflow as a single lineage.\"\"\"\n    tid = new_trace_id()\n\n    r = await orchestrator.dispatch_and_wait(\n        neuron=\"retriever\", input={\"question\": question, \"top_k\": top_k},\n        trace_id=tid, timeout_s=timeout_s,\n    )\n    out = r.payload[\"output\"]\n    if out.get(\"cache_hit\"):\n        return {\"answer\": out[\"answer\"], \"sources\": [], \"cached\": True}\n\n    r = await orchestrator.dispatch_and_wait(\n        neuron=\"reranker\",\n        input={\"question\": question, \"candidates\": out[\"candidates\"],\n               \"top_k\": top_k},\n        trace_id=tid, parent_id=r.id, timeout_s=timeout_s,\n    )\n    chunks = r.payload[\"output\"][\"chunks\"]\n\n    r = await orchestrator.dispatch_and_wait(\n        neuron=\"generator\",\n        input={\"question\": question, \"chunks\": chunks},\n        trace_id=tid, parent_id=r.id, timeout_s=timeout_s,\n    )\n    return {**r.payload[\"output\"], \"cached\": False}\n\n\ndef stats() -> dict:\n    return {\"vector_chunks\": VECTORS.size, \"keyword_chunks\": KEYWORDS.size,\n            \"cached_answers\": len(getattr(CACHE, \"_entries\", {}))}\n",
  "neurons/generator.py": "\"\"\"generator - grounded HF generation, imprints the answer cache.\"\"\"\nfrom cosmonapse import Axon, EngramBinding, Neuron\n\nfrom config import GEN_MODEL, SYSTEM_PROMPT, cache_key, hf_token\n\n\ndef make_generate_neuron():\n    \"\"\"{\"question\", \"chunks\"} -> {\"answer\", \"sources\"}. Caches the answer.\"\"\"\n    llm = Neuron(\n        source=\"huggingface\",\n        endpoint=\"https://router.huggingface.co\",\n        model=GEN_MODEL,\n        api_key=hf_token(),\n        use_chat_api=True,\n        max_new_tokens=512,\n        temperature=0.2,\n    )\n\n    async def generate_neuron(input, context, *, imprint):\n        question = input[\"question\"]\n        chunks = input[\"chunks\"]\n        if not chunks:\n            return {\"answer\": \"No relevant context found in the index.\",\n                    \"sources\": []}\n\n        blocks = [f\"[{c['id']}]\\n{c['text']}\" for c in chunks]\n        messages = [\n            {\"role\": \"system\", \"content\": SYSTEM_PROMPT},\n            {\"role\": \"user\", \"content\": (\n                \"Context:\\n\\n\" + \"\\n\\n---\\n\\n\".join(blocks)\n                + f\"\\n\\nQuestion: {question}\"\n            )},\n        ]\n        out = await llm({\"messages\": messages}, [])\n        answer = out[\"response\"].strip()\n\n        await imprint(\n            \"cache\", op=\"upsert\",\n            entry={\"content\": answer, \"tags\": [\"answer\"]},\n            merge_key=cache_key(question),\n            await_ack=False,\n        )\n        sources = [{\"id\": c[\"id\"], \"doc_id\": c[\"doc_id\"],\n                    \"chunk_index\": c[\"chunk_index\"], \"score\": c[\"score\"]}\n                   for c in chunks]\n        return {\"answer\": answer, \"sources\": sources}\n\n    return generate_neuron\n\n\ndef make_axon() -> Axon:\n    return Axon(\n        neuron_id=\"generator\", neuron_fn=make_generate_neuron(),\n        capabilities=[\"rag-generate\"],\n        engrams=[EngramBinding(name=\"cache\", directed_id=\"rag-cache\")],\n    )\n",
  "neurons/ingester.py": "\"\"\"ingester - chunk + embed, dual-imprints vectors AND keywords.\"\"\"\nfrom cosmonapse import Axon, EngramBinding\n\nfrom config import hf_token\nfrom embeddings import chunk_text, embed\n\n\nasync def ingest_neuron(input, context, *, imprint):\n    \"\"\"{\"doc_id\", \"text\"} -> {\"doc_id\", \"chunks\"}. Dual-writes both indexes.\"\"\"\n    doc_id = input[\"doc_id\"]\n    chunks = chunk_text(input[\"text\"])\n    vectors = await embed(chunks, api_key=hf_token())\n\n    for i, (chunk, vec) in enumerate(zip(chunks, vectors)):\n        last = i == len(chunks) - 1\n        entry = {\"doc_id\": doc_id, \"chunk_index\": i, \"text\": chunk}\n        await imprint(\n            \"vectors\", op=\"upsert\",\n            entry={**entry, \"embedding\": vec},\n            merge_key=f\"{doc_id}:{i}\", await_ack=last, deadline_ms=2000,\n        )\n        await imprint(\n            \"keywords\", op=\"upsert\",\n            entry=entry,\n            merge_key=f\"{doc_id}:{i}\", await_ack=last, deadline_ms=2000,\n        )\n    return {\"doc_id\": doc_id, \"chunks\": len(chunks)}\n\n\nAXON = Axon(\n    neuron_id=\"ingester\", neuron_fn=ingest_neuron,\n    capabilities=[\"rag-ingest\"],\n    engrams=[EngramBinding(name=\"vectors\", directed_id=\"rag-vectors\"),\n             EngramBinding(name=\"keywords\", directed_id=\"rag-keywords\")],\n)\n",
  "neurons/reranker.py": "\"\"\"reranker - lexical-overlap rescoring of fused candidates.\n\nCheap - swap in a cross-encoder Neuron without touching the pipeline.\n\"\"\"\nfrom cosmonapse import Axon\n\nfrom config import RRF_K, TOP_K\nfrom engram.keyword_engram import tokenize\n\n\nasync def rerank_neuron(input, context):\n    \"\"\"{\"question\", \"candidates\", \"top_k\"?} -> {\"chunks\": [...]}.\"\"\"\n    qterms = set(tokenize(input[\"question\"]))\n    top_k = int(input.get(\"top_k\", TOP_K))\n\n    rescored = []\n    for c in input[\"candidates\"]:\n        terms = set(tokenize(c[\"text\"]))\n        overlap = len(qterms & terms) / (len(qterms) or 1)\n        rescored.append({**c, \"score\": round(0.7 * c[\"rrf\"] * RRF_K + 0.3 * overlap, 4)})\n    rescored.sort(key=lambda c: c[\"score\"], reverse=True)\n    return {\"chunks\": rescored[:top_k]}\n\n\nAXON = Axon(\n    neuron_id=\"reranker\", neuron_fn=rerank_neuron,\n    capabilities=[\"rag-rerank\"],\n)\n",
  "neurons/retriever.py": "\"\"\"retriever - hybrid recall (semantic + lexical), RRF fusion, cache check.\"\"\"\nfrom cosmonapse import Axon, EngramBinding\n\nfrom config import FETCH_K, MIN_SCORE, RRF_K, TOP_K, cache_key, hf_token\nfrom embeddings import embed\n\n\nasync def retrieve_neuron(input, context, *, recall):\n    \"\"\"{\"question\", \"top_k\"?} -> {\"cache_hit\"} | {\"candidates\": [...]}.\n\n    Hybrid recall: semantic (vectors) + lexical (keywords), fused with\n    reciprocal-rank fusion. Checks the answer cache first.\n    \"\"\"\n    question = input[\"question\"]\n    top_k = int(input.get(\"top_k\", TOP_K))\n\n    # 0. Answer-cache short-circuit (exact normalised question).\n    cached = await recall(\n        \"cache\", query={\"merge_key\": cache_key(question)}, deadline_ms=500,\n    )\n    if cached.hits:\n        return {\"cache_hit\": True, \"answer\": cached.hits[0].entry[\"content\"]}\n\n    # 1. Both backends in their native query language.\n    qvec = (await embed([question], api_key=hf_token()))[0]\n    sem = await recall(\n        \"vectors\", query={\"embedding\": qvec, \"top_k\": FETCH_K},\n        min_confidence=MIN_SCORE, deadline_ms=2000,\n    )\n    lex = await recall(\n        \"keywords\", query={\"text\": question, \"top_k\": FETCH_K},\n        deadline_ms=2000,\n    )\n\n    # 2. Reciprocal-rank fusion across the two ranked lists.\n    fused: dict[str, dict] = {}\n    for hits in (sem.hits, lex.hits):\n        for rank, h in enumerate(hits):\n            key = f\"{h.entry['doc_id']}#{h.entry['chunk_index']}\"\n            slot = fused.setdefault(key, {\n                \"id\": key, \"doc_id\": h.entry[\"doc_id\"],\n                \"chunk_index\": h.entry[\"chunk_index\"],\n                \"text\": h.entry[\"text\"], \"rrf\": 0.0,\n            })\n            slot[\"rrf\"] += 1.0 / (RRF_K + rank + 1)\n\n    candidates = sorted(fused.values(), key=lambda c: c[\"rrf\"], reverse=True)\n    return {\"cache_hit\": False, \"candidates\": candidates[: top_k * 2]}\n\n\nAXON = Axon(\n    neuron_id=\"retriever\", neuron_fn=retrieve_neuron,\n    capabilities=[\"rag-retrieve\"],\n    engrams=[EngramBinding(name=\"vectors\", directed_id=\"rag-vectors\"),\n             EngramBinding(name=\"keywords\", directed_id=\"rag-keywords\"),\n             EngramBinding(name=\"cache\", directed_id=\"rag-cache\")],\n)\n",
  "receptors/api.py": "\"\"\"api - the RAG over HTTP.\n\n    curl -s localhost:8000/ingest -H 'content-type: application/json' \\\n         -d '{\"doc_id\": \"notes\", \"text\": \"...\"}'\n    curl -s localhost:8000/ask -H 'content-type: application/json' \\\n         -d '{\"question\": \"What is a Dendrite?\"}'\n    curl -s localhost:8000/stats\n\nPOST /ingest is the Receptor's own endpoint - one TASK to the ingester,\nwith send / wait / stream modes for free. /ask and /stats are extra routes\non the same router, because the pipeline is three TASKs on one trace.\nNeeds FastAPI + uvicorn: pip install 'cosmonapse[receptor]'\n\"\"\"\nfrom cosmonapse import ApiReceptor\n\nfrom engram.indexes import VECTORS\nfrom helpers import ask_pipeline, ingest_samples, stats as index_stats\n\nRECEPTOR = ApiReceptor(neuron=\"ingester\", path=\"/ingest\", timeout_s=120.0)\n\n\n@RECEPTOR.route(\"/ask\", methods=[\"POST\"])\nasync def ask(body: dict):\n    if VECTORS.size == 0:\n        await ingest_samples(RECEPTOR.dendrite)\n    return await ask_pipeline(RECEPTOR.dendrite, body[\"question\"],\n                              top_k=int(body.get(\"top_k\", 4)))\n\n\n@RECEPTOR.route(\"/stats\")\nasync def stats():\n    return index_stats()\n",
  "receptors/terminal.py": "\"\"\"terminal - ask the RAG from a shell.\n\n    python brain.py \"What is a Dendrite and what role does it play?\"\n    python brain.py stats\n    python brain.py                                   REPL (ask twice: cached)\n\n`ask` indexes sample_docs/ on first use, then runs the three-stage\npipeline. It is a local command because the pipeline is three TASKs, not\none - the Receptor's single dispatch is not the right shape for it.\n\"\"\"\nfrom cosmonapse import CliReceptor\n\nfrom engram.indexes import VECTORS\nfrom helpers import ask_pipeline, ingest_samples, stats as index_stats\n\nRECEPTOR = CliReceptor(\n    prog=\"rag\",\n    description=\"Hybrid-retrieval RAG over sample_docs/.\",\n    timeout_s=120.0,\n)\n\n\n@RECEPTOR.command(local=True, default=True, help=\"ask a question\")\nasync def ask(question: str):\n    if VECTORS.size == 0:\n        for doc in await ingest_samples(RECEPTOR.dendrite):\n            print(f\"  indexed {doc['doc_id']:<24} {doc['chunks']} chunks\")\n    out = await ask_pipeline(RECEPTOR.dendrite, question)\n    lines = [(\"(cached) \" if out[\"cached\"] else \"\") + out[\"answer\"]]\n    if out[\"sources\"]:\n        lines.append(\"sources: \" + \", \".join(f\"{s['id']} ({s['score']})\"\n                                             for s in out[\"sources\"]))\n    return \"\\n\".join(lines)\n\n\n@RECEPTOR.command(local=True, help=\"index sizes\")\ndef stats():\n    return index_stats()\n"
};
